package local.tvmorph.tv;
import android.app.*;import android.content.*;import android.widget.*;import java.net.*;import java.io.*;import java.util.concurrent.*;import org.json.*;
/** Forgotten parental PIN recovery proves ownership of the Plus code already bound to this device. */
final class ParentalRecovery {
 private static final ExecutorService worker=Executors.newSingleThreadExecutor();
 static void show(Activity activity,Runnable verified){EditText field=new EditText(activity);field.setSingleLine(true);field.setHint("MT-…");field.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_CAP_CHARACTERS);field.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(38)});field.setSaveEnabled(false);AlertDialog dialog=new LauncherDialog.Builder(activity).setTitle(FamilyText.t(activity,"نسيت الرقم السري؟","Forgot PIN?")).setMessage(FamilyText.t(activity,"أدخل كود تفعيل Plus المرتبط بهذا الجهاز. لن يتغير الاشتراك أو الأقفال المحفوظة.","Enter the Plus activation code linked to this device. Your subscription and saved locks will not change.")).setView(SystemTextInput.wrap(activity,field,false)).setPositiveButton(FamilyText.t(activity,"تحقق","Verify"),null).setNegativeButton(FamilyText.t(activity,"إلغاء","Cancel"),null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{String code=field.getText().toString().replaceAll("[\\s\\u200b-\\u200f\\u202a-\\u202e\\u2060\\u2066-\\u2069]","").replaceAll("[\\u2010-\\u2015\\u2212]","-").toUpperCase(java.util.Locale.ROOT).replace('0','O').replace('1','I');if(!code.matches("(?:MORPH-[A-Z2-7]{32}|MT-[A-Z2-7]{12})")){field.setError(FamilyText.t(activity,"راجع كود التفعيل.","Check the activation code."));return;}dialog.getButton(-1).setEnabled(false);worker.execute(()->{boolean allowed=false;try{String token=new JSONObject(PlusIdentity.read(activity)).optString("token");if(!token.isEmpty()){HttpURLConnection connection=(HttpURLConnection)new URL("https://morph-tv.com/api/plus/parent-reset").openConnection();try{connection.setConnectTimeout(8000);connection.setReadTimeout(8000);connection.setRequestMethod("POST");connection.setDoOutput(true);connection.setRequestProperty("Content-Type","application/json");byte[] bytes=new JSONObject().put("token",token).put("code",code).toString().getBytes("UTF-8");connection.setFixedLengthStreamingMode(bytes.length);try(OutputStream out=connection.getOutputStream()){out.write(bytes);}if(connection.getResponseCode()==200){ByteArrayOutputStream result=new ByteArrayOutputStream();try(InputStream in=connection.getInputStream()){byte[] chunk=new byte[1024];int n;while((n=in.read(chunk))!=-1){result.write(chunk,0,n);if(result.size()>16384)throw new IOException("Response too large");}}allowed=new JSONObject(result.toString("UTF-8")).optBoolean("allowed");}}finally{connection.disconnect();}}}catch(Exception ignored){}final boolean ok=allowed;activity.runOnUiThread(()->{if(activity.isDestroyed()||!dialog.isShowing())return;if(ok){field.setText("");dialog.dismiss();verified.run();}else{dialog.getButton(-1).setEnabled(true);field.setError(FamilyText.t(activity,"تعذّر التحقق. استخدم كود الجهاز نفسه وراجع اتصال الإنترنت.","Could not verify. Use this device’s code and check the internet connection."));}});});}));dialog.show();}
}
